INSERT INTO `soal` VALUES ('16','4','16','<p>Bertambahnya jumlah penduduk dipulau jawa mengakibatkan lahan pertanian semakin <br />sempit. Hal ini disebabkan adanya alih fungsi lahan, menjadi tempat permukiman. Dampak <br />dari pernyataan tersebut adalah ...</p>','1','<p>Semakin lemahnya harga pangan <br /><br /></p>','<p>Kebutuhan pangan <br /><br /></p>','<p>Meningkatnya pengangguran di sektor pertanian <br /><br /></p>','<p>Naiknya produksi pangan nasional</p>','','C','','','','','','',NULL);
