INSERT INTO `soal` VALUES ('18','4','18','<p>Ketika lapar, Haikal lebih memilih bakso, sementara Septian memilih satai, Riyan memilih <br />ayam goreng, sedangkan Afdzal memilih mie untuk memenuhi kebutuhan akan makanan. <br />Pernyataan tersebut menunjukkan perbedaan permintaan berdasarkan ....</p>','1','<p>Harga</p>','<p>Penghasilan <br /><br /></p>','<p>Selera <br /><br /></p>','<p>Kualitas Barang</p>','','C','','','','','','',NULL);
