INSERT INTO `soal` VALUES ('30','4','23','<p>Andi adalah seorang anak petani yang disekolahkan oleh orangtuanya hingga jenjang <br />universitas. Setelah lulus menjadi sarjana, ia melanjutan kuliah magister dan mimilih profesi <br />sebagai dosen. Sekarang ia sudah menjadapatkan gelar profesor. Saluran mobilitas sosial yang digunakan Andi adalah ....</p>','1','<p>Politik <br /><br /></p>','<p>Pendidikan <br /><br /></p>','<p>Pekerjaan <br /><br /></p>','<p>Ekonomi</p>','','B','','','','','','',NULL);
INSERT INTO `soal` VALUES ('31','4','24','<p>Keragaman budaya di Indonesia apabila tidak dikelola dengan baik, justru dapat <br />menimbulkan potensi konflik. Konflik yang mungkin terjadi adalah konflik anatar <br />kebudayaan, yaitu terdapat pihak yang merasa kebudayaannya paling baik. Hal tersebut <br />dikenal dengan istilah ....</p>','1','<p>Sentrisme <br /><br /></p>','<p>Sentimisme <br /><br /></p>','<p>Etnosentrisme <br /><br /></p>','<p>Sensitifisme</p>','','C','','','','','','',NULL);
