INSERT INTO `soal` VALUES ('50','4','41','<p>Salah satu bentuk pelestarian sumber daya air dilakukan oleh masyarakat didaerah lereng <br />gunung dengan menjaga kawasan resapan air melalui penanaman pohon keras dan larangan <br />membangun disekitar mata air. Apa manfaat jangka panjang dari kegiatan tersebut?</p>','1','<p>Meningkatkan peluang investasi properti</p>','<p>Membuat kawasan menjadi layak huni <br /><br /></p>','<p>Menurunkan suhu udara secara ekstrem <br /><br /></p>','<p>Menjaga ketersediaan air tanah dan mencegah kekeringan</p>','','D','','','','','','',NULL);
INSERT INTO `soal` VALUES ('51','4','42','<p>Diwilayah pesisir pantai utara jawa, nelayan mulai mengeluhkan hasil tangkapan yang <br />menurun drastis. Dalam dua tahun terakhir, banyak kapal besar dari luar daerah masuk dan <br />menggunakan alat tangkap tidak ramah lingkungan. Apa dampak utama dari penggunaan alat tangkap tidak ramah lingkungan terhadap keberlanjutan sumber daya laut?</p>','1','<p>Menurunnya kualitas air laut akibat pencemaran</p>','<p>Hilangnya mata pencaharian petani <br /><br /></p>','<p>Rusaknya terumbu karang dan kepunahan ikan-ikan kecil <br /><br /></p>','<p>Meningkatnya hasil tangkapan secara jangka panjang</p>','','C','','','','','','',NULL);
