INSERT INTO `soal` VALUES ('53','4','43','<p>Dalam sebuah debat sekolah, dua siswa membahas cara terbaik melestarikan tambang emas di Papua. Aulia menyarankan penghentian total kegiatan tambang, sementara Sindi <br />menyarankan penggunaan teknologi ramah lingkungan dan pemulihan lahan pasca tambang. Dari sudut pandang pembangunan berkelanjutan, pendapat siapa yang paling sesuai?</p>','1','<p>Aulia, karena semua aktivitas tambang merusak alam <br /><br /></p>','<p>Sindi, karena mempertimbangkan aspek ekonomi dan pelestarian lingkungan <br /><br /></p>','<p>Keduanya salah, karena emas tidak bisa habis <br /><br /></p>','<p>Keduanya benar, karena tambang tidak boleh disentuh sama sekali</p>','','B','','','','','','',NULL);
