INSERT INTO `soal` VALUES ('63','4','50','<p>Pak Azka adalah seorang kepala desa yang dipilih oleh masyarakat. Ia di hormati karena <br />perannya dalam memimpin dan membuat keputusan penting bagi desa. Status yang dimiliki <br />pak Azka termasuk .....</p>','1','<p>Ascribed status, karena ia dilahirkan sebagai pemimpin <br /><br /></p>','<p>Assigned status, karena ia diberikan oleh pemerintah pusat <br /><br /></p>','<p>&nbsp;Achieved status, karena diperoleh melalui pemilihan dan usaha <br /><br /></p>','<p>Status kultural, karena terkait budaya lokal</p>','','C','','','','','','',NULL);
