INSERT INTO `soal` VALUES ('80','8','6','<p>Kedatangan bangsa portugis ke Nusantara pada abad ke 16 tidak semata-mata karena <br />kekuatan militer, tetapi juga karena kondisi internal kerajaan-kerajaan di Indonesia saat itu. <br />Berdasarkan pernyataan tersebut, apa faktor yang paling memungkinkan bangsa portugis <br />dapat menguasai wilayah malaka?</p>','1','<p>Kerajaan-kerajaan lokal sedang mengalami konflik dan perpecahan <br /><br /></p>','<p>Portugis membawa teknologi cetak yang dibutuhkan oleh masyarakat lokal <br /><br /></p>','<p>Raja-raja nusantara bersedia tunduk karena tertarik dengan budaya eropa <br /><br /></p>','<p>Bangsa portugis memiliki peta jalur laut yang lebih akurat</p>','','A','','','','','','',NULL);
INSERT INTO `soal` VALUES ('81','8','7','<p>VOC dibentuk oleh Belanda bukan hanya untuk berdagang, tetapi juga untuk memperkuat <br />posisi mereka di Asia. Jika VOC tidak diberi hak istimewa seperti mencetak uang, membuat <br />perjanjian dan memiliki tentara sendiri, kemungkinan besar ...</p>','1','<p>VOC tetap mendominasi perdagangan rempah-rempah karena keunggulan teknologi <br /><br /></p>','<p>VOC lebih fokus berdagang di eropa <br /><br /></p>','<p>VOC hanya berfungsi sebagai perusahaan dagang biasa tanpa kekuasaan politik <br /><br /></p>','<p>VOC bekerjasama dengan inggris untuk menguasai pelabuhan strategis</p>','','C','','','','','','',NULL);
