INSERT INTO `soal` VALUES ('83','8','8','<p>Disebuah desa, terjadi ketegangan antara petani lokal dan pihak pengembang yang ingin <br />membangun perumahan diatas lahan pertanian produktif. Warga merasa Pembangunan itu <br />mengancam sumber mata pencaharian mereta. Ketegangan ini berujung pada unjuk rasa dan bentrokan kecil. Berdasarkan ilustrasi tersebut bentuk konflik sosial yang terjadi adalah &hellip;</p>','1','<p>Konflik antarindividu <br /><br /></p>','<p>Konflik antar kelompok sosial <br /><br /></p>','<p>Konflik masyarakat <br /><br /></p>','<p>Konflik ideologi</p>','','B','','','','','','',NULL);
