INSERT INTO `soal` VALUES ('94','8','14','<p>Rina ditangkap polisi karena mencuri dipusat perbelanjaan. Setelah dibebaskan, ia kembali <br />melakukan tindakan serupa ditempat lain. Penyimpangan sosial yang dilakukan rina termasuk ...</p>','1','<p>Penyimpangan budaya karena tidak sesuai dengan aturan yang berlaku <br /><br /></p>','<p>Penyimpangan sekunder karena dilakukan berulang dan melanggar hukum <br /><br /></p>','<p>Penyimpangan primer karena dilakukan berulang dan melanggar hukum <br /><br /></p>','<p>Penyimpangan positif karena menentang aturan hukum</p>','','B','','','','','','',NULL);
INSERT INTO `soal` VALUES ('95','7','7','<table style=\"width: 100%; border-collapse: collapse;\" border=\"1\">\r\n<tbody>\r\n<tr>\r\n<td style=\"width: 464px;\">\r\n<p><strong>How to make Strawberry Juice</strong></p>\r\n<p><strong><u>Ingredients:</u></strong></p>\r\n<p>5 large strawberries</p>\r\n<p>2 tablespoon sugar</p>\r\n<p>1/2 glass of water</p>\r\n<p>milk or yogurt (optional)</p>\r\n<p>ice cubes</p>\r\n<p><strong><u>Steps:&nbsp;</u></strong></p>\r\n<p>First, Slice the fruits.</p>\r\n<p>Then, put them into blender.</p>\r\n<p>Next, pour water, sugar and ice cubes.</p>\r\n<p>If you like it creamy, you may add milk or add yogurt if you prefer sour taste.</p>\r\n<p>After that, blend them for about 2 or 3 minutes.&nbsp;</p>\r\nAnd the last pour into the glass, add straw and the juice is ready to drink.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>What is the text about?</p>','1','<p>The description of strawberry</p>','<p>The way to make strawberry juice</p>','<p>The way to ask people to consume juice</p>','<p>How to drink strawberry juice</p>','','B','','','','','','',NULL);
