INSERT INTO `soal` VALUES ('100','8','18','<p>Pandemi covid-19 telah mengakibatkan krisis ekonomi di berbagai negara. Negara-negara <br />yang tergabung dalam organisasi G-20 memberikan kebijakan penangguhan pembayaran <br />utang luar negeri bagi negara berpenghasilan rendah. Berdasarkan pernyataan diatas, tujuan dari Kerjasama internasional tersebut adalah &hellip;</p>','1','<p>Memperluas pasar luar negeri <br /><br /></p>','<p>Mempercepat pertumbuhan ekonomi <br /><br /></p>','<p>Menghilangkan hambatan perdagangan <br /><br /></p>','<p>Mendukung percepatan teknologi</p>','','B','','','','','','',NULL);
