INSERT INTO `soal` VALUES ('102','8','19','<p>Berdasarkan peta jalur perdagangan Indonesia, khususnya wilayah seperti maluku menjadi <br />pusat penting dalam jalur perdagangan rempah-rempah. Apa keunggulan posisi geografis <br />Indonesia dalam perdagangan internasional pada masa itu&hellip;.</p>','1','<p>Indonesia berada dititik pertemuan jalur laut strategis antara Barat dan Timur <br /><br /></p>','<p>Indonesia terletak dijalur darat antara Eropa dan Asia <br /><br /></p>','<p>Indonesia memiliki banyak pelabuhan yang dilindungi benteng Belanda <br /><br /></p>','<p>Indonesia memiliki iklim dingin yang cocok untuk menanam rempah-rempah</p>','','A','','','','','','',NULL);
INSERT INTO `soal` VALUES ('103','8','20','<p>Permasalahan ekonomi yang muncul akibat pengangguran yang terjadi karena cepatnya <br />pertambahan penduduk tanpa disertai kesempatan kerja yang memadai adalah &hellip;</p>','1','<p>Meningkatnya kemiskinan <br /><br /></p>','<p>Munculnya kesenjangan sosial dalam masyarakat <br /><br /></p>','<p>Meningkatnya Tindakan kriminalitas <br /><br /></p>','<p>Ketidakstabilan kondisi politik dan keamanan</p>','','A','','','','','','',NULL);
