INSERT INTO `soal` VALUES ('148','8','48','<p data-start=\"2366\" data-end=\"2650\">Menjelang akhir masa Demokrasi Terpimpin, inflasi Indonesia mencapai angka yang sangat tinggi. Harga barang kebutuhan pokok meroket, dan nilai tukar rupiah terus melemah. Kondisi ini menyebabkan ketidakmampuan pemerintah dalam membiayai kebutuhan pokok rakyat dan pembangunan ekonomi.&nbsp;Apa dampak utama dari inflasi ekstrem pada masa ini?</p>','1','<p>Nilai ekspor naik tajam<br data-start=\"2737\" data-end=\"2740\" /><br /></p>','<p>Rakyat semakin mudah mendapat kredit<br data-start=\"2779\" data-end=\"2782\" /><br /></p>','<p>Daya beli masyarakat menurun drastis dan memperparah kemiskinan<br data-start=\"2848\" data-end=\"2851\" /><br /></p>','<p>Mata uang asing ditarik dari peredaran</p>','','C','','','','','','',NULL);
