INSERT INTO `soal` VALUES ('150','8','49','<p data-start=\"5324\" data-end=\"5542\">Meskipun pertumbuhan ekonomi pada masa Orde Baru tampak pesat, terjadi ketimpangan ekonomi antara elite dan masyarakat kecil. Hal ini diperparah oleh praktik korupsi, kolusi, dan nepotisme (KKN) dalam pemerintahan. Apa dampak dari praktik KKN terhadap kondisi ekonomi nasional?</p>','1','<p>Menurunnya investasi dan turunnya kepercayaan publik terhadap pemerintah<br data-start=\"5688\" data-end=\"5691\" /><br /></p>','<p>Meningkatnya produktivitas BUMN<br data-start=\"5725\" data-end=\"5728\" /><br /></p>','<p>Terbukanya lapangan kerja luas<br data-start=\"5761\" data-end=\"5764\" /><br /></p>','<p>Kesejahteraan masyarakat merata</p>','','A','','','','','','',NULL);
