INSERT INTO `soal` VALUES ('152','8','50','<p data-start=\"4684\" data-end=\"4976\">Untuk membiayai pembangunan, pemerintah Orde Baru bekerja sama dengan negara-negara donor dan lembaga keuangan internasional seperti IMF dan World Bank. Mereka membentuk IGGI (Inter-Governmental Group on Indonesia), yang kemudian berubah menjadi CGI (Consultative Group on Indonesia).</p>\r\n<p data-start=\"4978\" data-end=\"5288\">Apa tujuan dibentuknya IGGI dan CGI dalam kerangka pembangunan ekonomi Orde Baru?</p>','1','<p>Meningkatkan ketergantungan pada utang luar negeri<br data-start=\"5119\" data-end=\"5122\" /><br /></p>','<p>Mengatur diplomasi militer Indonesia<br data-start=\"5161\" data-end=\"5164\" /><br /></p>','<p>Menyediakan pinjaman dan bantuan guna mendukung pembangunan ekonomi nasional<br data-start=\"5243\" data-end=\"5246\" /><br /></p>','<p>Menarik tenaga kerja dari luar negeri</p>','','C','','','','','','',NULL);
