INSERT INTO `soal` VALUES ('503','19','3','<p>Tingali kalimah di handap ieu! Indung jeung Anak</p>\r\n<p>&ldquo;Mah, aya nu bad&eacute; ditaroskeun,&rdquo; ceuk Atia.&nbsp; Naroskeun naon?K&eacute;, Mamahna cap&eacute; k&eacute;n&eacute;h,&rdquo; jawab indungna. Geus biasa, lamun tas nyanyabaan, Atia mah sok tetelep&eacute;k ngeunaan naon-naon anu kat&eacute;njo atawa nu kaalaman, boh di perjalanan boh di tempat nu dituju. Harita og&eacute; kakara jol pisan tas piknik ti Maribaya.</p>\r\n<p>Sok, bad&eacute; naroskeun naon? Mani bangun daria,&rdquo; ceuk indungna deui, bari neuteup&hellip; br&eacute;h budak t&eacute;h mani ngembang c&eacute;ng&eacute;k.&ldquo;Kieu, Mah ....., naon margina ari na&eacute;k mobil sok istri heula, ari lungsur sok pameget heula. Geuning tadi og&eacute;, basa na&eacute;k angkot, Bapamah tipengker na&eacute;kna ..... lungsurna mah tipayun,&rdquo; pokna.</p>\r\n<p>Naon nu jadi t&eacute;ma dina &eacute;ta paguneman t&eacute;h?</p>','1','<p>Piknik ti Maribaya</p>','<p>Na&eacute;k mobil jeung turun mobil</p>','<p>Indung jeung anak</p>','<p>Tatakrama naek jeung turun tina mobil</p>','','D','','','','','','',NULL);
