INSERT INTO `soal` VALUES ('1103','22','3','<p>Perhatikan beberapa tugas berikut!</p>\r\n<ol>\r\n<li>Menyembah Allah</li>\r\n<li>Mengajarkan wahyuAllah</li>\r\n<li>Menyampaikan wahyu kepada</li>\r\n<li>Membimbing manusia pada manusia</li>\r\n</ol>\r\n<p>Memberikan rezeki Allah Swt. kepadaTugas rasul Allah Swt. ditunjukan oleh angka</p>','1','<p>1), 2), dan 3)</p>','<p>1), 2), dan 4)</p>','<p>2), 3), dan 4)</p>','<p>2), 4), dan 4)</p>','','B','','','','','','','');
INSERT INTO `soal` VALUES ('1104','22','4','<p>Pasangan yang tepat antara sifat wajib dan sifat mustahil terdapat pada angka&hellip;.</p>','1','<p>1) dan 2)</p>','<p>2) dan 3)</p>','<p>2) dan 4)</p>','<p>3) dan 4)</p>','','C','22_4_1.png','','','','','','');
INSERT INTO `soal` VALUES ('1105','22','5','<p>Allah Swt. mengutus para rasul untuk menyampaikan wahyu-Nya. wahyu tersebut langsung disampaikan para rasul Allah swt. mereka Tidak sekali pun menyembunyikan wahyu-wahyu allah swt.</p>\r\n<p>Isi paragraph tersebut menunjukan bahwa rasul Allah swt. memiliki sifat</p>','1','<p>Siddiq</p>','<p>Amanah</p>','<p>Tabglig</p>','<p>Fatanah</p>','','C','','','','','','','');
INSERT INTO `soal` VALUES ('1106','22','6','<p>Pernyataan yang tepat tentang rasul allah swt. yaitu. . . .</p>','1','<p>rasul Allah Swt. merupakan manusia pilihan yang memiliki kewajiban menyampaikan wahyu-nya</p>','<p>rasul Allah Swt. seluruhnya berjumlah 25</p>','<p>rasul allah swt yang wajib di ketahui ada 25</p>','<p>Nabi Adam a.s merupakan rasul ulul azmi pertama</p>','','A','','','','','','','');
INSERT INTO `soal` VALUES ('1107','22','7','<p>Sifat siddiq merupakan salah satu sifat wajib bagi rasul allah swt. Lawan dari sifat siddiq yaitu&hellip;</p>','1','<p>Kazib</p>','<p>Khianat</p>','<p>Kitman</p>','<p>Baladah</p>','','A','','','','','','','');
INSERT INTO `soal` VALUES ('1108','22','8','<p>Allah Swt. mengutus rasul-nya degan memberberikan wahyu masing-masing. Meskipun demikian, semua rasul Allah Swt. Memiliki satu kesamaan misi yaitu mengajarkan perintah&hellip;&hellip;.</p>','1','<p>Beribadah kepada Allah Swt.</p>','<p>Berpuasa pada bulan Ramadhan</p>','<p>Melaksanakan salat fardu</p>','<p>Membayar zakat dan haji</p>','','A','','','','','','','');
INSERT INTO `soal` VALUES ('1109','22','9','<p>Perhatikan cerita berikut !</p>\r\n<p>Beliau merupakan salah satu nabi dan rasul Allah Swt. dari keturunan Nabi Yakub a.s.Beliau dikenal memiliki kecerdasan tinggi. Pada saat masih kecil beliau diangkat menjadi anak oleh Siti Asiyah, istri Raja Fir`aun.</p>\r\n<p>Cerita di atas merupakan kisah&hellip;&hellip;</p>','1','<p>Nabi Musa a.s.</p>','<p>Nabi Harun a.s.</p>','<p>Nabi Zakaria a.s.</p>','<p>Nabi Sulaiman a.s.</p>','','A','','','','','','','');
