INSERT INTO `soal` VALUES ('1138','22','38','<p>Pa Salman menyembelih seekor sapi untuk kurban. Setelah sapi disembelih dan darah <br />mengalir, pak salman menampung darah tersebut di ember. Setelah itu, pak Salman <br />membekukan darah tersebut dan mengolah menjadi makann yang lezat. Hukum mengkonsumsi darah tersebut haram karena</p>','1','<p>Darah sapi seharusnya langsun diolah dan tidak dibekukan</p>','<p>Darah merupakan jenis makanan yang yang tidak boleh dikonsumsi</p>','<p>Sapi merupakan salah satu hewan yang diharamkan oleh Allah SWT</p>','<p>Sapi tersebut merupakan sapi kurban yang darahnya harus dibagikan kepada orang lain</p>','','B','','','','','','','');
