INSERT INTO `soal` VALUES ('1216','30','3','<p>Sebelum Islam datang, masyarakat Mekkah hidup dalam kondisi yang jauh dari nilai-nilai kebenaran, baik dari segi moral maupun akidahnya. Kondisi ini disebut dengan istilah</p>','1','<p>Masyarakat post-tradisional</p>','<p>Masyarakat jahiliyah</p>','<p>Masyarakat madani</p>','<p>Masyarakat trasional</p>','','B','','','','','','',NULL);
INSERT INTO `soal` VALUES ('1217','30','4','<p>Bangsa Arab sebelum Islam datang banyak yang menyembah selain Allah SWT, ada yang menyembah berhala, benda-benda langit dan lainnya, adapun agama yang mengajarkan bahwa Allah SWT adalah satu-satunya Tuhan yang patut disembah adalah ajaran&hellip;</p>','1','<p>Atheisme</p>','<p>Animisme</p>','<p>Tauhid</p>','<p>Polytheisme</p>','','C','','','','','','',NULL);
INSERT INTO `soal` VALUES ('1218','30','5','<p>azirah Arab pada masa sebelum Islam diapit oleh dua kekaisaran besar yaitu</p>','1','<p>Kekaisaran Romawi dan Saba</p>','<p>Kekaisaran Kindah dan Himyariyah</p>','<p>Kekaisaran Romawi dan Persia</p>','<p>Kekaisaran Saba` dan Kindah</p>','','C','','','','','','',NULL);
INSERT INTO `soal` VALUES ('1219','30','6','<p>Orang-orang yang pertama kali masuk Islam dalam sejarah dikenal dengan sebutan Assabiqunal Awwalun, berikut yang termasuk Assabuqunal Awwalun adalah</p>','1','<p>Abu Tholib, Siti Khotijah, Ali bin Abu Tholib dan Zaid bin Haritsah</p>','<p>Siti Khotijah, Ali bin Abi Tholib, Abu Bakar as-Shiddiq dan Abdurrahman bin Auf</p>','<p>Umayyah bin Kholaf, Bilal bin Rabbah, Tsumayya dan Ummu Aiman</p>','<p>Zaid bin Haritsah, Zaid bin Tsabit, Muawiyah bin Abu Sofyan dan Amr bin Ash</p>','','B','','','','','','',NULL);
INSERT INTO `soal` VALUES ('1220','30','7','<p>Berikut adalah pernyataan yang benar tentang pola dakwah Islam di Makkah secara Jahr (terang-terangan) kecuali</p>','1','<p>Dakwah secara terang-terangan pertama kali dilakukan di bukit Shofa</p>','<p>Sasaran dakwah secara jahr adalah kerabat dekat Rasulullah SAW</p>','<p>Dasar pelaksanaan dakwah secara jahr adalah Q.S.al-Hijr : 94</p>','<p>Rintangan dakwah semakin berat setelah dilakukan dakwah secara jahr</p>','','B','','','','','','',NULL);
