INSERT INTO `soal` VALUES ('1232','30','19','<p>Pernyataan yang benar tentang respon kaum kafir Quraisy setelah mengetahui sebagian kaum muslimin melakukan hijrah ke Habsyi adalah</p>','1','<p>Kaum kafir Quraisy menangkap dan menahan Usman bin Affan</p>','<p>Kaum kafir Quraisy menantang raja Habsyi untuk berperang</p>','<p>Kaum kafir Quraisy menghasut raja Habsyi supaya menolak kaum muslimin</p>','<p>Kaum kafir Quraisy menangkap dua puteri Nabi Muhammad SAW untuk dijadikan tawanan perang</p>','','C','','','','','','',NULL);
INSERT INTO `soal` VALUES ('1233','30','20','<p>Salah satu alasan Rasulullah SAW memilih kota Thaif sebagai alternatif tempat dakwah Islam setelah kota Makkah adalah</p>','1','<p>Ayah Rasulullah SAW berasal dari Thaif</p>','<p>Thaif merupakan kota yang luas wilayahnya</p>','<p>Di Thaif ada salah satu suku Arab yaitu Bani Tsaqif</p>','<p>Jarak antara kota Makkah dengan Thaif sangat jauh</p>','','C','','','','','','',NULL);
