INSERT INTO `soal` VALUES ('1236','30','23','<p><em>Perhatikan tabel berikut ! NO ISI PERJANJIAN NO ISI PERJANJIAN </em></p>\r\n<p><em>1 Setia kepada Nabi Muhammad SAW </em></p>\r\n<p><em>4 Tidak melakukan kecurangan dan dusta </em></p>\r\n<p><em>2 Siap dan bersedia melindungi dakwah Nabi Muhammad SAW </em></p>\r\n<p><em>5 Ikut berusaha memajukan agama Islam </em></p>\r\n<p><em>3 Siap menerima segala resiko dan tantangan </em></p>\r\n<p><em>6 Tidak menyekutukan Allah SWT </em></p>\r\n<p><em>Yang termasuk Isi Baiat al-Aqobah II adalah </em></p>','1','<p><em>1, 2 dan 3 </em></p>','<p><em>1, 4 dan 5 </em></p>','<p><em>3, 5 dan 6 </em></p>','<p><em>2, 3 dan 5 </em></p>','','D','','','','','','',NULL);
