INSERT INTO `soal` VALUES ('1238','30','25','<p>Perhatikan pernyataan dibawah ini !</p>\r\n<ol>\r\n<li>Selalu mengedepankan kepentingan pribadi dan kelompok</li>\r\n<li>Kegigihan dan keuletan dalam menyebarkan agama Islam</li>\r\n<li>Memiliki keyakinan yang kuat</li>\r\n<li>Kedzaliman harus dilawan dengan kekerasan</li>\r\n<li>Mengakui kesetaraan derajat manusia&nbsp; &nbsp;Dari pernyataan di atas yang termasuk kunci keberhasilan dakwah Nabi Muhammad SAW. di Mekkah adalah ....</li>\r\n</ol>','1','<p>2, 3 dan 5</p>','<p>1, 2 dan 3</p>','<p>3, 4 dan 5</p>','<p>2, 4 dan 5</p>','','A','','','','','','',NULL);
